CREATE TABLE public.recycling_businesses(user_id uuid PRIMARY KEY REFERENCES public.profiles(id), approved boolean NOT NULL DEFAULT false, public_ranking boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.recycling_businesses TO authenticated; GRANT ALL ON public.recycling_businesses TO service_role;
ALTER TABLE public.recycling_businesses ENABLE ROW LEVEL SECURITY;
CREATE POLICY recycling_business_read ON public.recycling_businesses FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.recycling_partners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE NOT NULL REFERENCES public.profiles(id),company_name text NOT NULL CHECK(length(company_name) BETWEEN 1 AND 150),approved boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.recycling_partners TO authenticated; GRANT ALL ON public.recycling_partners TO service_role;
ALTER TABLE public.recycling_partners ENABLE ROW LEVEL SECURITY;
CREATE POLICY recycling_partner_read ON public.recycling_partners FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.recycling_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),points_per_kg numeric NOT NULL DEFAULT 10 CHECK(points_per_kg BETWEEN 0 AND 10000),rewards jsonb NOT NULL DEFAULT '[{"points":100,"percent":5},{"points":250,"percent":10},{"points":500,"percent":15}]',winner_percents integer[] NOT NULL DEFAULT ARRAY[20,15,10],expiry_days integer NOT NULL DEFAULT 30 CHECK(expiry_days BETWEEN 1 AND 365),max_discount numeric NOT NULL DEFAULT 100 CHECK(max_discount>0),minimum_order numeric NOT NULL DEFAULT 0 CHECK(minimum_order>=0));
GRANT SELECT ON public.recycling_settings TO authenticated; GRANT ALL ON public.recycling_settings TO service_role;
ALTER TABLE public.recycling_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY recycling_settings_read ON public.recycling_settings FOR SELECT TO authenticated USING(true);
CREATE TABLE public.recycling_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),buyer_id uuid NOT NULL REFERENCES public.profiles(id),partner_id uuid REFERENCES public.recycling_partners(id),estimated_weights jsonb NOT NULL,actual_weights jsonb NOT NULL DEFAULT '{}',city text NOT NULL CHECK(length(city) BETWEEN 1 AND 100),location text NOT NULL CHECK(length(location) BETWEEN 1 AND 500),status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','assigned','accepted','scheduled','collected','verified','rejected')),scheduled_at timestamptz,collected_at timestamptz,verified_at timestamptz,verified_by uuid,verified_kg numeric NOT NULL DEFAULT 0,confirmed_recycled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),request_key uuid UNIQUE NOT NULL);
GRANT SELECT ON public.recycling_requests TO authenticated; GRANT ALL ON public.recycling_requests TO service_role;
ALTER TABLE public.recycling_requests ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.recycling_access(rid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.recycling_requests r WHERE r.id=rid AND (r.buyer_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.recycling_partners p WHERE p.id=r.partner_id AND p.user_id=auth.uid() AND p.approved))) $$;
REVOKE ALL ON FUNCTION public.recycling_access(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.recycling_access(uuid) TO authenticated;
CREATE POLICY recycling_request_read ON public.recycling_requests FOR SELECT TO authenticated USING(public.recycling_access(id));
CREATE TABLE public.recycling_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES public.recycling_requests(id),kind text NOT NULL CHECK(kind IN ('photo','receipt','evidence')),storage_path text UNIQUE NOT NULL,file_name text NOT NULL CHECK(length(file_name) BETWEEN 1 AND 200),uploaded_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.recycling_files TO authenticated; GRANT ALL ON public.recycling_files TO service_role;
ALTER TABLE public.recycling_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY recycling_file_read ON public.recycling_files FOR SELECT TO authenticated USING(public.recycling_access(request_id));
CREATE TABLE public.green_points_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),amount numeric NOT NULL CHECK(amount<>0),source_key text UNIQUE NOT NULL,request_id uuid REFERENCES public.recycling_requests(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.green_points_ledger TO authenticated; GRANT ALL ON public.green_points_ledger TO service_role;
ALTER TABLE public.green_points_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY green_ledger_read ON public.green_points_ledger FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.green_vouchers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),percent integer NOT NULL CHECK(percent BETWEEN 1 AND 100),maximum_discount numeric NOT NULL CHECK(maximum_discount>0),minimum_order numeric NOT NULL DEFAULT 0 CHECK(minimum_order>=0),expires_at timestamptz NOT NULL,issued_at timestamptz NOT NULL DEFAULT now(),source_key text UNIQUE NOT NULL,is_demo boolean NOT NULL DEFAULT true,used_order_id uuid UNIQUE REFERENCES public.orders(id),used_at timestamptz);
GRANT SELECT ON public.green_vouchers TO authenticated; GRANT ALL ON public.green_vouchers TO service_role;
ALTER TABLE public.green_vouchers ENABLE ROW LEVEL SECURITY;
CREATE POLICY green_voucher_read ON public.green_vouchers FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.recycling_months(period date PRIMARY KEY,finalized_at timestamptz NOT NULL DEFAULT now(),finalized_by uuid NOT NULL,results jsonb NOT NULL);
GRANT SELECT ON public.recycling_months TO authenticated; GRANT ALL ON public.recycling_months TO service_role;
ALTER TABLE public.recycling_months ENABLE ROW LEVEL SECURITY;
CREATE POLICY recycling_month_read ON public.recycling_months FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.green_supplier_consent(supplier_id uuid PRIMARY KEY REFERENCES public.supplier_profiles(id),approved boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.green_supplier_consent TO authenticated; GRANT ALL ON public.green_supplier_consent TO service_role;
ALTER TABLE public.green_supplier_consent ENABLE ROW LEVEL SECURITY;
CREATE POLICY green_consent_read ON public.green_supplier_consent FOR SELECT TO authenticated USING(true);
ALTER TABLE public.orders ADD COLUMN green_voucher_id uuid REFERENCES public.green_vouchers(id),ADD COLUMN green_discount numeric NOT NULL DEFAULT 0;
CREATE FUNCTION public.recycling_weights(w jsonb) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE k text; v jsonb; total numeric:=0; n numeric; BEGIN
IF jsonb_typeof(w) IS DISTINCT FROM 'object' OR w='{}'::jsonb THEN RAISE EXCEPTION 'Eligible weights required'; END IF;
FOR k,v IN SELECT * FROM jsonb_each(w) LOOP IF k NOT IN ('paper','cardboard','aluminum') OR jsonb_typeof(v)<>'number' THEN RAISE EXCEPTION 'Only paper, cardboard and aluminum'; END IF; n:=v::text::numeric; IF n<=0 OR n>100000 OR n<>round(n,3) THEN RAISE EXCEPTION 'Invalid weight'; END IF; total:=total+n; END LOOP; RETURN total; END $$;
CREATE FUNCTION public.recycling_rankings(month_start date) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',user_id,'name',business_name,'kg',kg,'rank',rank) ORDER BY rank),'[]'::jsonb) FROM (SELECT r.buyer_id user_id,b.business_name,sum(r.verified_kg) kg,row_number() OVER(ORDER BY sum(r.verified_kg) DESC,min(r.verified_at),r.buyer_id) rank FROM public.recycling_requests r JOIN public.recycling_businesses rb ON rb.user_id=r.buyer_id AND rb.approved AND rb.public_ranking JOIN public.business_profiles b ON b.user_id=r.buyer_id WHERE r.status='verified' AND (r.verified_at AT TIME ZONE 'Asia/Gaza')::date>=month_start AND (r.verified_at AT TIME ZONE 'Asia/Gaza')::date<(month_start+interval '1 month')::date GROUP BY r.buyer_id,b.business_name) x $$;
REVOKE ALL ON FUNCTION public.recycling_rankings(date) FROM PUBLIC;
CREATE FUNCTION public.recycling_public_board() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE period date:=date_trunc('month',now() AT TIME ZONE 'Asia/Gaza')::date; history jsonb; ranking jsonb; BEGIN
SELECT coalesce(jsonb_agg(jsonb_build_object('period',m.period,'winners',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',x->>'name','kg',x->'kg','rank',x->'rank') ORDER BY (x->>'rank')::int),'[]'::jsonb) FROM jsonb_array_elements(m.results) x JOIN public.recycling_businesses rb ON rb.user_id=(x->>'user_id')::uuid AND rb.public_ranking WHERE (x->>'rank')::int<=3)) ORDER BY m.period DESC),'[]'::jsonb) INTO history FROM (SELECT * FROM public.recycling_months ORDER BY period DESC LIMIT 12) m;
SELECT coalesce(jsonb_agg(x-'user_id'),'[]'::jsonb) INTO ranking FROM jsonb_array_elements(public.recycling_rankings(period)) x;
RETURN jsonb_build_object('period',period,'rankings',ranking,'history',history); END $$;
REVOKE ALL ON FUNCTION public.recycling_public_board() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.recycling_public_board() TO anon,authenticated;